def transform(grid):
    h,w=len(grid),len(grid[0])
    counts={}
    for row in grid:
        for v in row: counts[v]=counts.get(v,0)+1
    bg=max(counts,key=counts.get)
    out=[row[:] for row in grid]
    for r0 in range(h):
      for r1 in range(r0+2,h):
       for c0 in range(w):
        for c1 in range(c0+2,w):
         sides=[r0==0 or all(grid[r0][c]!=bg for c in range(c0,c1+1)),
                r1==h-1 or all(grid[r1][c]!=bg for c in range(c0,c1+1)),
                c0==0 or all(grid[r][c0]!=bg for r in range(r0,r1+1)),
                c1==w-1 or all(grid[r][c1]!=bg for r in range(r0,r1+1))]
         if all(sides) and sum([r0==0,r1==h-1,c0==0,c1==w-1])<=1:
          # keep only pockets whose three drawn sides are continuous and interior is background
          if all(grid[r][c]==bg for r in range(r0+1,r1) for c in range(c0+1,c1)):
           for r in range(r0+1,r1):
            for c in range(c0+1,c1): out[r][c]=4
    return out
